Translate("ruRU", "stranglethorn-vale", {
	title = "Тернистая долина",
	aliases = { "Тернистая", "Долина" },
	sections = {
		{
			title = "Обзор",
			text = [=[Тернистая долина — великие джунгли юга. Они тянутся от мрачных рубежей {link:duskwood}Сумеречного леса{/link} до скалистого мыса, где суша обрывается в море. Деревья здесь стары и высоки, реки кишат кроколисками, а под зеленым сводом охотятся тигры, пантеры, ящеры и обезьяны. Повсюду лианы поглотили камни павшей империи троллей. Ни одна корона не правит этим краем. Гоблины держат порт {link:booty-bay}Пиратская бухта{/link}, {link:horde}Орда{/link} стоит лагерем на западном берегу, охотники и дезертиры с севера разбивают шатры в холмах, а племена троллей ведут свои старые войны в руинах отцов.]=],
		},
		{
			title = "Истоки",
			text = [=[Некогда здесь было сердце Гурубаши, лесных троллей юга. В века до {link:great-sundering}Великого Раскола{/link} их империя простиралась по этим землям и далеко за их пределы. Когда мир раскололся, империя уступила морю многие свои земли, и ее народ в нужде обратился к темному поклонению. Жрецы Атал'ай призвали в своей столице {link:zul-gurub}Зул'Гуруб{/link} бога крови {link:hakkar}Хаккара{/link}. Бог кормился теми, кто ему поклонялся, и наконец племена восстали против него и его жрецов. Они изгнали бога, а жрецов Атал'ай прогнали в болота на севере. Империя Гурубаши так и не оправилась. Ее племена пошли друг на друга, а построенные ими города достались джунглям.]=],
		},
		{
			title = "Наши дни",
			text = [=[У Тернистой долины нет хозяина, и потому хозяев у нее много. Гоблины {link:steamwheedle-cartel}картеля Хитрая Шестеренка{/link} правят Пиратской бухтой на южной оконечности, где рады любому флагу, пока он платит. Пираты двух враждующих флотилий, {red:blackwater-raiders}Пираты Черноводья{/red} и {red:bloodsail-buccaneers}пираты Кровавого Паруса{/red}, бьются за воды мыса. {link:venture-company}Торговая Компания{/link} обдирает северные холмы ради древесины и кристаллов. На севере отряд солдат {link:stormwind-city}Штормград{/link}а ведет отчаянную войну против собственного бывшего полковника. На западном берегу {link:horde}Орда{/link} возвела {link:grom-gol-base-camp}Гром'гол{/link}, и посланники {link:darkspear-trolls}племени Черного Копья{/link} вернулись на родину искать пропавшего сына своего племени. Знаменитый охотник {link:hemet-nesingwary}Хеминг Эрнестуэй{/link} прибыл охотиться на великих зверей джунглей. А за всем этим по-прежнему стоят тролли: племя Кровавого Скальпа, Дробители Черепов и последователи изгнанника {link:zanzil-the-outcast}Занзил{/link}а — и каждые все еще воюют с остальными.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}Гоблины Пиратской бухты.{/b} Купцы, посредники и вышибалы картеля {link:steamwheedle-cartel}Хитрая Шестеренка{/link}, а с ними Пираты Черноводья, что пьют в их тавернах.
• {b}Пираты Кровавого Паруса.{/b} Пираты-соперники, которые высадились на Пустынном берегу и строят козни против порта.
• {b}Племена Гурубаши.{/b} {link:trolls}Тролли{/link} Кровавого Скальпа в руинах на северо-западе, Дробители Черепов в руинах в середине долины и последователи знахаря {link:zanzil-the-outcast}Занзил{/link}а на мысу. За стенами {link:zul-gurub}Зул'Гуруб{/link}а все еще шевелятся более древние силы.
• {b}Повстанцы и дезертиры.{/b} Повстанцы лейтенанта {link:lieutenant-doren}Дорен{/link}а на севере и люди полковника {link:colonel-kurzen}Курцен{/link}а в лагере к востоку от них.
• {b}{link:horde}Орда{/link} в {link:grom-gol-base-camp}Гром'гол{/link}е.{/b} {link:orcs}Орки{/link} и {link:darkspear-trolls}тролли Черного Копья{/link}, которые охраняют путь снабжения в {link:stonard}Каменор{/link} и дирижабли на север.
• {b}Охотники.{/b} {link:hemet-nesingwary}Хеминг Эрнестуэй{/link} и его спутники, что стоят лагерем у северной реки.
• {b}{link:ogres}Огры{/link}.{/b} Клан {link:mosh-ogg-ogre-mound}Мош'Огг{/link} держит холм в восточных горах и руины Мизжа.
• {b}{link:naga}Наги{/link}, {link:murlocs}мурлок{/link}и и морские великаны.{/b} Они населяют побережья, затонувшие руины и рифы.]=],
		},
		{
			title = "История",
			text = [=[• {b}Империя.{/b} Долгие века Гурубаши правили этими джунглями из {link:zul-gurub}Зул'Гуруб{/link}а. Их каменные города вставали вдоль рек и побережий.
• {b}{link:hakkar}Свежеватель Душ{/link}.{/b} Жрецы Атал'ай призвали в мир бога Хаккара. Поклонение ему привело империю к междоусобной войне, а его поражение оставило ее разбитой.
• {b}Рассеяние.{/b} Племена Гурубаши дрались друг с другом за то, что осталось. {link:darkspear-trolls}Племя Черного Копья{/link} изгнали из джунглей, и оно ушло на острова Южных морей.
• {b}Гоблины.{/b} Гоблины выбили троллей из гавани на южной оконечности джунглей и построили в ней Пиратскую бухту. Ни одна летопись джунглей не называет года.
• {b}Наши дни.{/b} Северяне приходят сюда все в большем числе: солдаты, охотники, рудокопы и {link:horde}Орда{/link}. Никто из них не укротил Долину.]=],
		},
		{
			title = "Предания джунглей",
			text = [=[• Говорят, что каждый народ {link:azeroth}Азерот{/link}а считает воды святого источника на западных утесах даром, освященным для него одного.
• Солдаты лагеря повстанцев рассказывают друг другу, будто гоблины Пиратской бухты затаскивают пьяных матросов на невольничьи суда и увозят туда, чего никто не называет.
• Болезнь, которую зовут лихорадкой Тернистой долины, валит с ног моряков на мысу. Единственное лекарство, по словам знахарей, — сердце белой обезьяны, которую никто не может найти.
• {link:hemet-nesingwary}Хеминг Эрнестуэй{/link} написал книгу о своих охотах в джунглях. Однажды ее страницы унес ветер, и говорят, что джунгли до сих пор прячут несколько из них.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не называет годов, когда империя Гурубаши возвысилась, пала или рассеялась, и года, когда гоблины взяли Пиратскую бухту.]=],
		},
	},
})

Translate("ruRU", "booty-bay", {
	title = "Пиратская бухта",
	sections = {
		{
			title = "Обзор",
			text = [=[Пиратская бухта — порт гоблинов на южной оконечности Тернистой долины. Путь в него из джунглей лежит через туннель в скалах, а сам город лепится к стенам глубокой бухты: кольцо за кольцом деревянных домов и мостков вокруг тесной гавани. {link:baron-revilgaz}Барон Ревилгаз{/link} правит им с верхнего этажа таверны. Вышибалы {link:steamwheedle-cartel}картеля Хитрая Шестеренка{/link} хранят мир между {link:alliance}Альянс{/link}ом и Ордой, а {red:blackwater-raiders}Пираты Черноводья{/red} заполняют его постоялые дворы между плаваниями. От его причалов корабли ходят за море, в {link:ratchet}Кабестан{/link}. Здесь можно купить что угодно, а продать — почти все.]=],
		},
	},
})

Translate("ruRU", "gurubashi-arena", {
	title = "Арена Гурубаши",
	aliases = { "арена" },
	sections = {
		{
			title = "Обзор",
			text = [=[Арена Гурубаши — {link:ogres}огр{/link}омное каменное кольцо в сердце джунглей, возведенное троллями во дни их империи. Ее ярусы, растрескавшиеся и заросшие, все еще стоят вокруг песчаной площадки. Троллей здесь больше нет. Время от времени пират {link:short-john-mithril}Коротышка Джон Мифрил{/link} ставит на песок сундук с сокровищами и позволяет самым отважным бойцам джунглей убивать друг друга ради него. Те, кто побеждает снова и снова, говорит он, могут называть себя мастерами арены.]=],
		},
	},
})

Translate("ruRU", "zul-gurub", {
	title = "Зул'Гуруб",
	sections = {
		{
			title = "Обзор",
			text = [=[Зул'Гуруб был великим городом троллей Гурубаши, и из него их империя некогда правила югом. Здесь жрецы Атал'ай призвали в мир Свежевателя Душ {link:hakkar}Хаккара{/link}, и здесь же племена восстали, чтобы низвергнуть его. Город лежит на северо-востоке джунглей, за стенами, которых не сломали лианы. Его ворота затворены. Воины Гурубаши и жрецы Хаккари все еще несут перед ними стражу, и среди них ходит верховная жрица. Те, кто живет поблизости, не спрашивают, что делается внутри.]=],
		},
		{
			title = "В эти дни",
			text = [=[{link:darkspear-trolls}Племя Черного Копья{/link} не забыло этот город. Именно Зул'Гурубу племя некогда отдало младшего сына вождя, {link:yenniku}Йеннику{/link}, как того требовал обычай. Ныне {link:vol-jin}Вол'джин{/link} говорит о грядущих битвах с его троллями. А недавно видели, как за стенами города наблюдает тролль далекого племени Зандалар.]=],
		},
	},
})

Translate("ruRU", "nesingwary-s-expedition", {
	title = "Экспедиция Эрнестуэя",
	aliases = { "лагерь Эрнестуэя" },
	sections = {
		{
			title = "Обзор",
			text = [=[Экспедиция Эрнестуэя — охотничий лагерь на севере джунглей, выше по реке от разработок Торговой Компании на озере {link:lake-nazferiti}Назферити{/link}. Его шатры стоят вокруг костра, а охотничьи трофеи выставлены под открытым небом. Здесь собрались {link:dwarves}дворф{/link} {link:hemet-nesingwary}Хеминг Эрнестуэй{/link} и его спутники, чтобы охотиться на великих зверей Тернистой долины: тигров, пантер и ящеров, а более всего — на одного белого тигра. Охотники рады чужакам, которые метко стреляют. На всех прочих терпения у них мало.]=],
		},
	},
})

Translate("ruRU", "rebel-camp", {
	title = "Лагерь Повстанцев",
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Повстанцев лежит на дальнем севере джунглей, близ дороги, что спускается из {link:duskwood}Сумеречного леса{/link}. Это небольшой частокол с шатрами и ящиками, который держат солдаты {link:stormwind-city}Штормград{/link}а: некогда они шли за полковником {link:colonel-kurzen}Курцен{/link}ом, а теперь обратились против него. Ими командует лейтенант {link:lieutenant-doren}Дорен{/link}. Их мало, и люди полковника превосходят их числом во много раз. Гоблины Пиратской бухты шлют им припасы, а среди припасов — мины, чтобы стеречь подступы к лагерю. Каждый солдат здесь знает, что один-единственный предатель может погубить их всех.]=],
		},
	},
})

Translate("ruRU", "kurzen-s-compound", {
	title = "Лагерь Курцена",
	aliases = { "Схрон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Курцена лежит к востоку от Лагеря Повстанцев, в северных холмах. Его строили солдаты, и это заметно. Ограды, вышки и штабеля припасов расставлены с толком, а в единственном двухэтажном доме некогда помещалась контора полковничьего хранителя припасов. Ныне лагерь держат бойцы джунглей, лекари и коммандос. В его тылу в холме открывается пещера. {link:humans}Люди{/link} полковника называют ее Схроном, и в ее глубине командует сам полковник {link:colonel-kurzen}Курцен{/link}.]=],
		},
	},
})

Translate("ruRU", "grom-gol-base-camp", {
	title = "Лагерь Гром'гол",
	aliases = { "Гром'гол" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Гром'гол — застава вождя на западном берегу Тернистой долины. {link:horde}Орда{/link} пришла в джунгли не затем, чтобы воевать с их племенами. Она пришла держать открытым путь снабжения в {link:stonard}Каменор{/link}, свою крепость в болотах на северо-востоке. Но на дорогах охотятся ящеры, {link:ogres}огр{/link}ы устраивают засады на караваны, и лагерю приходится сражаться за каждый прожитый день. С его башен дирижабли поднимаются к {link:orgrimmar}Оргриммару{/link} и {link:undercity}Подгороду{/link}. Здесь трудятся и посланники племени Черного Копья, у которых свое поручение.]=],
		},
	},
})

Translate("ruRU", "ruins-of-zul-kunda", {
	title = "Руины Зул'Кунды",
	aliases = { "Зул'Кунда" },
	sections = {
		{
			title = "Обзор",
			text = [=[Руины Зул'Кунды стоят на северо-западном побережье джунглей, где город троллей некогда глядел на море. Ныне их держит племя Кровавого Скальпа. Вождь племени {link:gan-zulah}Ган'зула{/link} и его знахарь {link:nezzliok-the-dire}Неззлиок Жуткий{/link} обитают в глубине руин, а их охотники за головами рыщут вдоль побережья до самых Руин Зуулдая. Среди разбитых камней все еще стоят две резные таблички со старинными преданиями троллей. Те, кто приходит их переписать, редко задерживаются.]=],
		},
	},
})

Translate("ruRU", "ruins-of-zul-mamwe", {
	title = "Руины Зул'Мамбве",
	aliases = { "Зул'Мамбве" },
	sections = {
		{
			title = "Обзор",
			text = [=[В середине джунглей, к востоку от Арены Гурубаши, лежат земли племени Дробителей Черепов. Их деревни стоят в Руинах Балиа'ма, Руинах Зиата'джаи и Руинах Зул'Мамбве, и в каждой сложена груда черепов-трофеев, взятых у врагов. Дробители Черепов воюют с племенем Кровавого Скальпа на севере и с памятью о племени Черного Копья. Их вождь — Ана'тек Жестокий, а их знахаря Мога называют Бессмертным. Клыки у них большие и красивые, и некоторые гоблины нашли им применение, которое не понравилось бы покупателям тигриных клыков.]=],
		},
	},
})

Translate("ruRU", "mizjah-ruins", {
	title = "Руины Мизжа",
	sections = {
		{
			title = "Обзор",
			text = [=[Руины Мизжа лежат к юго-востоку от {link:grom-gol-base-camp}Гром'гол{/link}а, за рекой. Некогда это был город троллей. Теперь его заняла шайка {link:ogres}огр{/link}ов, и с его стен огры нападают на караваны снабжения Орды на дороге через джунгли. Предостережениям Гром'гола никто не внял, и у командира лагеря кончилось терпение. За рекой напротив руин в подлеске крадутся пантеры и тигрицы.]=],
		},
	},
})

Translate("ruRU", "mosh-ogg-ogre-mound", {
	title = "Холм Мош'Огг",
	aliases = { "Мош'Огг", "огры Мош'Огг" },
	sections = {
		{
			title = "Обзор",
			text = [=[Холм Мош'Огг лежит в восточных горах Тернистой долины, недалеко к югу от {link:zul-gurub}Зул'Гуруб{/link}а. Это твердыня клана {link:ogres}огров{/link} Мош'Огг: молотобойцев, поджигателей войны, шаманов и лордов. В глубине обитал огр-маг {link:mai-zoth}Май'Зот{/link}, знавший джунгли с тех дней, когда в них еще жило племя Черного Копья. Огры Мош'Огг к тому же любят азартные игры и не любят проигрывать. Человека, который однажды выиграл у них слишком много, выгнали с холма вместе с его выигрышем.]=],
		},
	},
})

Translate("ruRU", "lake-nazferiti", {
	title = "Озеро Назферити",
	aliases = { "Назферити", "Главный лагерь Торговой компании" },
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Назферити лежит на севере джунглей, и на его берегах {link:venture-company}Торговая Компания{/link} построила свою базу. Ее крошшеры валят лес, а ее геологи роют холмы в поисках странных синих кристаллов. Десятник Коззл держит свои чертежи под замком у себя в доме. У Торговой Компании нет друзей в Тернистой долине. Торговцы Пиратской бухты ее ненавидят, барон направил против нее своих агентов, и сами джунгли, кажется, противятся ей.]=],
		},
	},
})

Translate("ruRU", "crystalvein-mine", {
	title = "Хрустальная шахта",
	sections = {
		{
			title = "Обзор",
			text = [=[Хрустальная шахта лежит в холмах к юго-востоку от {link:grom-gol-base-camp}Гром'гол{/link}а. В ее стенах скрыты поющие кристаллы, каких нет нигде, кроме Тернистой долины, и она кишит василисками. Звери поедают кристалл, и он делает их шкуры тверже, так что убитый василиск может дать осколки не хуже добытых из породы. Из-за василисков {link:venture-company}Торговая Компания{/link} не может войти в шахту и потому добывает кристалл в холмах вокруг нее. Говорят, что осколки поют тем, кто умеет их слышать.]=],
		},
	},
})

Translate("ruRU", "the-vile-reef", {
	title = "Коварный риф",
	sections = {
		{
			title = "Обзор",
			text = [=[Коварный риф лежит под водами Гибельного берега, к северо-западу от {link:grom-gol-base-camp}Гром'гол{/link}а. Давным-давно великое содрогание земли п{link:ogres}огр{/link}узило здесь в воду город троллей, и его улицы теперь лежат под морем. {link:trolls}Тролли{/link} дали месту это имя потому, что в затонувших руинах поселились {link:murlocs}мурлок{/link}и и нападают на всех, кто подходит близко. Среди руин стоит каменная табличка, повествующая о герое преданий троллей Гри'леке. {link:darkspear-trolls}Племя Черного Копья{/link} чтит это предание как священное.]=],
		},
	},
})

Translate("ruRU", "nek-mani-wellspring", {
	title = "Родник Нек'Мани",
	aliases = { "Святой источник" },
	sections = {
		{
			title = "Обзор",
			text = [=[Высоко на утесах западного побережья, к югу от Арены Гурубаши, лежит источник, который ученые называют святым. Никто не согласен в том, чей он. Каждый народ {link:azeroth}Азерот{/link}а, говорят шаманы, утверждает, будто его воды были благословлены для него одного, и жрецы с мистиками спорят о нем столько, сколько помнит любой из живущих. Теперь из моря поднялась экспедиция {link:naga}наг{/link} и захватила источник. Что нагам от него нужно, никто не узнал.]=],
		},
	},
})

Translate("ruRU", "the-cape-of-stranglethorn", {
	title = "Мыс Тернистой долины",
	sections = {
		{
			title = "Обзор",
			text = [=[Мыс Тернистой долины — южный край джунглей, где суша сужается между двумя морями к Пиратской бухте. По Мглистой долине к востоку от порта бродят большие обезьяны. На восточном берегу мыса, Хрустальном взморье, стоят {link:ruins-of-aboraz-and-jubuwal}Руины Абораза{/link} и Руины Жубуваля, где изгнанник {link:zanzil-the-outcast}Занзил{/link} держит своих последователей. В потаенной пещере на южном мысу живет знахарь, говорящий с духами. Пираты Кровавого Паруса высадились на Пустынном берегу к югу. Мыс — самый оживленный уголок Тернистой долины и один из самых опасных.]=],
		},
	},
})

Translate("ruRU", "ruins-of-aboraz-and-jubuwal", {
	title = "Руины Абораза и Жубуваля",
	aliases = { "Руины Абораза", "Руины Жубуваля", "Абораз", "Жубуваль" },
	sections = {
		{
			title = "Обзор",
			text = [=[К северо-востоку от Пиратской бухты, на Хрустальном взморье, стоят два разрушенных города троллей: Абораз и Жубуваль. Это владения знахаря, изгнанного собственным племенем; его зовут {link:zanzil-the-outcast}Занзил Изгнанник{/link}. Его последователи живут на его зелье и не задают ему вопросов. Здесь ходят и мертвые. Три игрока из Пиратской бухты, не сумевшие заплатить долги, бродят теперь по этим руинам, проклятые и околдованные. Среди рабов знахаря некогда был юный тролль Черного Копья, пропавший сын вождя.]=],
		},
	},
})

Translate("ruRU", "jaguero-isle", {
	title = "Остров Жагуаро",
	sections = {
		{
			title = "Обзор",
			text = [=[Остров Жагуаро лежит у юго-восточного побережья мыса. Он дик и густо зарос джунглями, а его звери повинуются {link:ogres}огр{/link}омной обезьяне, королю Мукле. По его берегам крадутся пантеры. Мало кто из моряков пристает сюда, а те, кто пристает, не находят гавани. С пляжей острова в ясный день виден {link:wild-shore}Пустынный берег{/link} на северо-западе и высокие корабли пиратов на юго-западе. Их видела когда-то и одна пленница, и она бросила в море послание.]=],
		},
	},
})

Translate("ruRU", "wild-shore", {
	title = "Пустынный берег",
	aliases = { "Лагерь Кровавого Паруса", "Кровавая Завеса" },
	sections = {
		{
			title = "Обзор",
			text = [=[Пустынный берег — самое южное побережье Тернистой долины, за скалами Пиратской бухты. Здесь {red:bloodsail-buccaneers}пираты Кровавого Паруса{/red} возвели лагерь, который называют своим южным командным пунктом. У берега стоят на якоре три их корабля: {i}«Кровавая Завеса»{/i}, {i}«Бурун»{/i} и {i}«Госпожа Удача»{/i}. Под палубами {i}«Кровавой Завесы»{/i} командующий флотом {link:fleet-master-firallon}Фираллон{/link} готовит свою войну против Пиратской бухты. На этом берегу не место тому, кто не ходит под цветами Кровавого Паруса.]=],
		},
	},
})

Translate("ruRU", "green-hills-of-stranglethorn", {
	title = "Зеленые холмы Тернистой долины",
	found = [=[Ее страницы разбросаны по джунглям; Барнил Каменный Котелок собирает их в Экспедиции Эрнестуэя]=],
	aliases = { "Зеленые холмы Тернистой долины" },
	sections = {
		{
			title = "Обзор",
			text = [=[{i}«Зеленые холмы Тернистой долины»{/i} — книга об охотах в джунглях, которую {link:hemet-nesingwary}Хеминг Эрнестуэй{/link} написал собственной рукой. Его спутник {link:barnil-stonepot}Барнил Каменный Котелок{/link} вычитывал ее для него, когда порыв ветра разметал ее страницы по Тернистой долине. Книга состоит из четырех глав. Первая описывает место действия и называет спутников охотника. Вторая полна рассказов о тиграх и пантерах. Третья повествует о первой добыче, которую {link:sir-s-j-erlgadin}сэр Эрлгадин{/link} и {link:ajeck-rouack}леди Руак{/link} взяли из {link:dwarves}дворф{/link}ийского ружья, и обрывается на самом напряженном месте. Четвертая — великий финал. Барнил надеется увидеть книгу в библиотеках всего мира.]=],
		},
	},
})

Translate("ruRU", "baron-revilgaz", {
	title = "Барон Ревилгаз",
	subtitle = "Владыка Пиратской бухты",
	found = "Пиратская бухта, верхний этаж таверны по ту сторону гавани",
	hint = [=[Поднимитесь на самый верх таверны, что смотрит на гавань Пиратской бухты.]=],
	allegiance = "Пиратская бухта · Картель Хитрая Шестеренка",
	aliases = { "Ревилгаз" },
	sections = {
		{
			title = "Обзор",
			text = [=[Барон Ревилгаз — гоблин, владыка Пиратской бухты. С верхнего этажа таверны он надзирает за гаванью, кораблями, торговлей и ссорами порта. Его собственный народ называет его самым отъявленным пиратом побережья, и никто из знающих его в этом не сомневается. Он богат, горд и не прощает тех, кто встает ему поперек дороги. Еще он собирает древние реликвии империй троллей и готов потратить уйму чужого времени, чтобы поставить на свои полки еще одну.]=],
		},
		{
			title = "Значение",
			text = [=[Ревилгаз — закон Пиратской бухты. Пираты Кровавого Паруса знают: пока он жив, им придется говорить с портом на условиях порта, и они дорого заплатили бы, чтобы увидеть его мертвым. Его агенты следят за Торговой Компанией, среди его друзей есть архимаги {link:kirin-tor}Кирин-Тора{/link}, а его монета доходит до самых гоночных полей {link:kalimdor}Калимдор{/link}а.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он правит Пиратской бухтой и держит ее открытой для каждого корабля, который платит.
• Он держит агентов, таких как {link:kebok}Кебок{/link} и {link:krazek}Кразек{/link}, которые приносят ему слухи и тихо улаживают его затруднения.
• Он велел агенту Кебоку разобраться с гоблином, который начал оттеснять магнатов торговых принцев.
• Он покровительствует гоблину-гонщику {link:pozzik}Поззик{/link}у и ради него послал за чертежами топливного регулятора Торговой Компании.
• Ему уже доводилось иметь дело с архимагом {link:dalaran}Даларана{/link} {link:archmage-ansirem-runeweaver}Ансиремом Ткачом Рун{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Камень Приливов",
			hint = [=[Принесите барону весть об острове с привидениями и идите туда, куда она поведет.]=],
			text = [=[Моряки в таверне толковали об острове у побережья, где обитают водные элементали и неистовый призрак гоблина. {link:krazek}Кразек{/link} передал рассказ дальше, и Ревилгаз вспомнил предание троллей, которое когда-то читал: Камень Приливов, реликвия, что обрекает своего владельца то исчезать из мира, то возвращаться в него. Говорили, что ее нашел гоблин-волшебник Газбан. Ревилгаз не пожелал покидать Пиратскую бухту, чтобы самому беседовать с занудными магами, и потому отправил наручи элементалей в {link:dalaran}Даларан{/link}. {link:archmage-ansirem-runeweaver}Ансирем{/link} нашел след проклятия и кинжал троллей, способный его разрушить. Теперь Камень занимает почетное место в собрании барона.]=],
		},
		{
			title = "Услуга покровителя",
			hint = [=[Попросите у барона помощи для гоблина-гонщика с Мерцающей равнины.]=],
			text = [=[Гоблину-гонщику {link:pozzik}Поззик{/link}у обещали новый топливный регулятор из Пиратской бухты, но он так и не пришел. Крошшеры Торговой Компании на озере {link:lake-nazferiti}Назферити{/link} работали на новой конструкции, и их десятник держал ее чертежи под замком. Ревилгаз хотел, чтобы их скопировали — ради гонщика и ради собственных записей. Он не любит, когда его гонщики думают, будто покровители их бросили.]=],
		},
	},
	mentions = {
		{ text = "Остров с привидениями" },
		{ text = "Камень Приливов" },
		{ text = "Водные элементали" },
		{ text = "Магическое исследование" },
		{ text = "Проклятие приливов" },
		{ text = "Покровительство гоблинов" },
		{ text = "Покровительство гоблинов" },
		{ text = "Покровительство гоблинов" },
		{ text = "Враждебное поглощение" },
		{ text = "Стой, адмирал!" },
	},
	bonds = {
		{ id = "krazek", name = "Кразек", note = "приносит ему слухи" },
		{ id = "kebok", name = "Кебок", note = "его агент в Пиратской бухте" },
		{ id = "archmage-ansirem-runeweaver", name = "Архимаг Ансирем Ткач Рун", note = "маг, прочитавший проклятие" },
		{ id = "catelyn-the-blade", name = "Кэтлин Клинок", note = "одолжила свой кинжал его делу" },
		{ id = "fleet-master-seahorn", name = "Командующий флотом Морской Рог", note = "начальник флота, который охраняет порт" },
		{ id = "fleet-master-firallon", name = "Командующий флотом Фираллон", note = "желает ему смерти" },
	},
})

Translate("ruRU", "hemet-nesingwary", {
	title = "Хеминг Эрнестуэй",
	subtitle = "Охотник на великих зверей",
	found = "Экспедиция Эрнестуэя, на севере джунглей",
	hint = [=[Найдите охотника-дворфа, чей лагерь стоит выше по реке от озера Назферити.]=],
	allegiance = "Экспедиция Эрнестуэя · Альянс",
	aliases = { "Эрнестуэй", "Хеминг Эрнестуэй-младший", "мастер Эрнестуэй", "Хеминг" },
	sections = {
		{
			title = "Обзор",
			text = [=[Хеминг Эрнестуэй — {link:dwarves}дворф{/link}, охотник и рассказчик охотничьих историй. Спутники называют его прославленным героем {link:alliance}Альянс{/link}а: он сражался на полях битв {link:lordaeron}Лордерона{/link}, прежде чем взялся за ружье ради забавы. Он охотился по всему миру. Теперь он прибыл в Тернистую долину с отрядом товарищей-охотников, и один зверь более всех привел его сюда: белый тигр, король {link:king-bangalash}Бангалаш{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Эрнестуэй знаменит, богат и имеет большие связи. Даже гоблины Пиратской бухты стараются разузнать, чем он занят. Он гордится своим мастерством и щедр к любому, кто может с ним сравниться, какого бы тот ни был народа и знамени. Он записал повесть о своих охотах в джунглях, и его спутники надеются, что ее будут читать по всему миру.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он разбил лагерь у северной реки; с ним {link:barnil-stonepot}Барнил Каменный Котелок{/link}, {link:ajeck-rouack}Аджек Руак{/link} и сэр С. Дж. {link:sir-s-j-erlgadin}Эрлгадин{/link}.
• Он испытывает новичков в охоте на ящеров, тогда как Аджек оценивает их в охоте на тигров, а сэр Эрлгадин — на пантер.
• Он охотился на зверей {link:desolace}Пустошей{/link} вместе с {link:tauren}таурен{/link}ом {red:roon-wildmane}Руном Буйногривым{/red}, и оба стали друзьями вопреки старой вражде их народов.
• Перед отъездом в джунгли он заказал ящик особых боеприпасов у одного гоблина с Мерцающей равнины.
• Он написал {i}«{link:green-hills-of-stranglethorn}Зеленые холмы Тернистой долины{/link}»{/i}, историю своих охот.]=],
		},
	},
	chapters = {
		{
			title = "Мастера охоты",
			hint = "Покажите себя в охоте на ящеров джунглей.",
			text = [=[Охотники лагеря не делят свой костер с кем попало. Хеминг назначает испытания без обиняков: сначала ящеры, затем породы побыстрее, затем ящеры-охотники джунглей, выследить которых труднее всего. Последнее испытание — самка ящера Тетис, которую сам Хеминг так и не убил. Того, кто принесет ее коготь, называют мастером охоты на ящеров.]=],
		},
		{
			title = "Белый тигр",
			hint = [=[Выследите зверя, который привел дворфа-охотника в Тернистую долину.]=],
			text = [=[Когда Син'Далл, Баг'тера и Тетис пали, Хеминг рассказал правду о своем приезде. Не ради них он пересек море. Он приехал за белым тигром, королем {link:king-bangalash}Бангалаш{/link}ем, который не раз заставлял его ковылять обратно в лагерь. Когда тигр был убит, Хеминг прокричал «ура» в честь охотника, сделавшего то, чего не смог он сам, и назвал этого охотника товарищем экспедиции.]=],
		},
		{
			title = "Старые друзья",
			hint = "Доставьте охотнику подарок от далекого друга.",
			text = [=[Подарки и теперь находят дорогу в лагерь через море. Гоблин-торговец с Мерцающей равнины переслал ящик боеприпасов, за который Хеминг заплатил задолго до того. Таурен из Пустошей прислал рог кодо, а с ним — приглашение снова поохотиться вместе. Хеминг был рад и тому, и другому. Сейчас он глубоко в джунглях, но земли {link:centaurs}кентавр{/link}ов не забыл.]=],
		},
	},
	mentions = {
		{ text = "Добро пожаловать в джунгли" },
		{ text = "Мастерство охоты на ящеров" },
		{ text = "Мастерство охоты на ящеров" },
		{ text = "Мастерство охоты на ящеров" },
		{ text = "Мастерство охоты на ящеров" },
		{ text = "Охотник на крупную дичь" },
		{ text = "Хеминг Эрнестуэй" },
		{ text = "Охота в Тернистой долине" },
		{ text = "Разведать лагерь" },
		{
			text = [=[{link:green-hills-of-stranglethorn}Зеленые холмы Тернистой долины{/link}]=],
		},
	},
	bonds = {
		{ id = "barnil-stonepot", name = "Барнил Каменный Котелок", note = "его спутник и корректор" },
		{ id = "ajeck-rouack", name = "Аджек Руак", note = "его спутница, мастер охоты на тигров" },
		{ id = "sir-s-j-erlgadin", name = "Сэр С. Дж. Эрлгадин", note = "его спутник, мастер охоты на пантер" },
		{ id = "king-bangalash", name = "Король Бангалаш", note = "добыча, ради которой он приехал" },
		{ id = "roon-wildmane", name = "Рун Буйногривый", note = "его друг по охоте в Пустошах" },
		{ id = "krazek", name = "Кразек", note = "следит за его лагерем для гоблинов" },
	},
})

Translate("ruRU", "lieutenant-doren", {
	title = "Лейтенант Дорен",
	subtitle = "Предводитель повстанцев",
	found = "Лагерь Повстанцев, на дальнем севере джунглей",
	hint = [=[Отыщите офицера, который возглавляет повстанцев близ дороги из Сумеречного леса.]=],
	allegiance = "Королевство Штормград · Лагерь Повстанцев",
	aliases = { "Дорен" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лейтенант Дорен командует повстанцами Тернистой долины. Он и его солдаты некогда служили полковнику {link:colonel-kurzen}Курцен{/link}у и были ему беззаветно преданы. Потом полковник переменился. Чем глубже Курцен п{link:ogres}огр{/link}ужался в жестокость, тем вернее преданность его людей обращалась в ярость, и Дорен увел тех, кто не желал больше идти за полковником, в отдельный лагерь. С тех пор они воюют со своим прежним командиром.]=],
		},
		{
			title = "Значение",
			text = [=[Дорен ведет войну, которую не может выиграть в одиночку. {link:colonel-kurzen}Курцен{/link} — блестящий тактик, и его люди превосходят повстанцев числом во много раз. Повстанцы держатся на припасах гоблинов, на краденых лекарствах и на тайнах. Эти тайны лейтенант должен беречь крепко, ибо одно слово не в то ухо может приставить нож к горлу его солдат.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он удерживает {link:rebel-camp}Лагерь Повстанцев{/link} против сил полковника.
• Он отправил рядового {link:private-thorsen}Торсен{/link}а лазутчиком обратно к людям полковника.
• Он разыскивал записи Букмекера {link:herod}Ирод{/link}а, хранителя припасов полковника, чтобы узнать, как была выдана тайна рядового Торсена.
• Он нашел предателя в собственном лагере.
• Он послал своего бойца в {link:kurzen-s-compound}Схрон{/link}, чтобы тот встретился лицом к лицу с самим полковником.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна запись не говорит, как рота лейтенанта оказалась на службе в Тернистой долине и когда повстанцы порвали со своим полковником.]=],
		},
	},
	chapters = {
		{
			title = "Предатель в лагере",
			hint = "Помогите лейтенанту узнать, кто выдал его лазутчика.",
			text = [=[О задании знали только трое: Дорен, сержант {link:sergeant-yohwa}Йохва{/link} и сам {link:private-thorsen}Торсен{/link}. И все же люди полковника тоже о нем узнали. В сундучке хранителя припасов лежала перепачканная грязью записка, где перечислялись дозоры рядового Торсена, его друзья и его привычки, подписанная одной-единственной буквой. Остальное рассказали расписания дозоров. Всю ту неделю стражу с ним делил рядовой Мерль. Дорен считал его храбрым солдатом с верным сердцем. Открытие причинило ему боль, но облегчения принесло больше.]=],
		},
		{
			title = "Падение полковника",
			hint = "Отнесите надежду повстанцев в Схрон.",
			text = [=[Когда ряды бойцов джунглей поредели, а особые отряды полковника были разбиты, Дорен попросил о последнем и самом трудном деле. Тому, кто сражался за повстанцев, предстояло войти в {link:kurzen-s-compound}Схрон{/link}, пройти мимо защитников полковника и встретиться с ним и его капитанами. Дорен едва поверил донесению, когда оно пришло. Впервые с начала восстания его солдаты могли вздохнуть свободнее.]=],
		},
	},
	mentions = {
		{ text = "Тайны джунглей" },
		{ text = "Букмекер {link:herod}Ирод{/link}" },
		{ text = "Лазутчик раскрыт!" },
		{ text = "Расписания дозоров" },
		{ text = "Доложить лейтенанту Дорену" },
		{ text = "Особые отряды" },
		{ text = "{link:colonel-kurzen}Полковник Курцен{/link}" },
	},
	bonds = {
		{ id = "colonel-kurzen", name = "Полковник Курцен", note = "его бывший командир и враг" },
		{ id = "sergeant-yohwa", name = "Сержант Йохва", note = "его сержант, которой он доверяет" },
		{ id = "private-thorsen", name = "Рядовой Торсен", note = "его лазутчик" },
		{ id = "brother-nimetz", name = "Брат Нимец", note = "ищет причину падения полковника" },
		{ id = "krazek", name = "Кразек", note = "шлет лагерю припасы" },
	},
})

Translate("ruRU", "nimboya", {
	title = "Нимбойя",
	subtitle = "Посланник племени Черного Копья",
	found = "Лагерь Гром'гол",
	hint = [=[Поговорите в Гром'голе с троллем Черного Копья, который ищет пропавшего сына своего племени.]=],
	allegiance = "Племя Черного Копья · Орда",
	sections = {
		{
			title = "Обзор",
			text = [=[Нимбойя — тролль {link:darkspear-trolls}племени Черного Копья{/link}, присланный обратно в Тернистую долину из далекого {link:orgrimmar}Оргриммара{/link}. Его поручение тяжко. По старому обычаю его народа младшего сына его вождя, {link:yenniku}Йеннику{/link}, отдали троллям Гурубаши из {link:zul-gurub}Зул'Гуруб{/link}а. Когда племя Черного Копья покинуло джунгли, чтобы последовать за вождем {link:thrall}Траллом{/link}, мальчик остался позади и пропал. Нимбойя пришел найти его, живым или мертвым.]=],
		},
		{
			title = "Значение",
			text = [=[Нимбойя говорит от имени племени Черного Копья в земле, которую оно некогда звало домом. Через него племя ведет свои самые старые распри и исполняет самые новые обязанности перед {link:horde}Ордой{/link}: поиски юного {link:yenniku}Йеннику{/link}, войну с племенем Кровавого Скальпа, наказание Сухокожих, предавших вождя, и замысел, который вынашивает {link:vol-jin}Вол'джин{/link}, — добыть меч {link:trol-kalar}Трол'калар{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он охотился на племя Кровавого Скальпа ради вестей о пропавшем.
• Он осмотрел великое множество засушенных голов и возблагодарил духов, когда головы мальчика среди них не оказалось.
• Бурлящим котлом он вырвал правду у отрубленных голов вождя Кровавого Скальпа и его знахаря.
• Он отправил свою пику на север, во {link:the-hinterlands}Внутренние земли{/link}, как мрачное послание троллям Сухокожих.
• Он направляет бойцов Орды в {link:hammerfall}Павший Молот{/link}, к охотнику {link:zengu}Зенгу{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Головы, которые заговорили",
			hint = [=[Принесите головы вождя Кровавого Скальпа и его знахаря к котлу посланника.]=],
			text = [=[Нимбойя боялся, что тролли Кровавого Скальпа убили мальчика, и поклялся наложить на их вождя шестисотлетнее проклятие, если это так. Головы вождя Ган'зулы и знахаря {link:nezzliok-the-dire}Неззлиок{/link}а отправились в его котел, и мертвые заговорили. Они торговались даже тогда и требовали трофеев и крови, прежде чем ответить. {link:nak}Нак{/link}онец Неззлиок сказал правду. {link:yenniku}Йеннику{/link} жив, но больше себе не принадлежит. Им, телом и душой, владеет знахарь {link:zanzil-the-outcast}Занзил Изгнанник{/link}.]=],
		},
		{
			title = "Спасение пропавшего сына",
			hint = "Верните домой пропавшего сына племени Черного Копья.",
			text = [=[После этого надежда стала слабой — малой, как самая малая букашка, сказал Нимбойя. Но {link:kin-weelay}Кин'вилай{/link} узнал от духов, где лежит Око Разума. Его вырвали у {link:ogres}огр{/link}а {link:mai-zoth}Май'Зот{/link}а, и знахарь превратил его в самоцвет, способный вместить душу. С его помощью {link:yenniku}Йеннику{/link} был оглушен, а его дух вырван из хватки изгнанника, и самоцвет доставили в {link:grom-gol-base-camp}Гром'гол{/link}. Нимбойя считал свое поручение безнадежным. Он пообещал, что племя воспоет этот подвиг и высечет его в камне.]=],
		},
	},
	mentions = {
		{ text = "Охота за {link:yenniku}Йеннику{/link}" },
		{ text = "Охота за головами" },
		{ text = "Головы клана Кровавого Скальпа" },
		{
			text = [=[Разговор со знахарем {link:nezzliok-the-dire}Неззлиок{/link}ом]=],
		},
		{ text = "Разговор с вождем Ган'зулой" },
		{ text = "Судьба {link:yenniku}Йеннику{/link}" },
		{ text = "Спасение {link:yenniku}Йеннику{/link}" },
		{ text = "Троллебой" },
		{ text = "Мрачное послание" },
	},
	bonds = {
		{ id = "yenniku", name = "Йеннику", note = "сын вождя, которого он ищет" },
		{ id = "kin-weelay", name = "Кин'вилай", note = "его товарищ-посланник" },
		{ id = "gan-zulah", name = "Ган'зула", note = "проклят им" },
		{ id = "nezzliok-the-dire", name = "Неззлиок Жуткий", note = "говорил из котла" },
		{ id = "zanzil-the-outcast", name = "Занзил Изгнанник", note = "держал юного Йеннику" },
		{ id = "zengu", name = "Зенгу", note = "охотник, посланный за мечом Трол'калар" },
		{ id = "vol-jin", name = "Вол'джин", note = "отдает ему приказы" },
	},
})

Translate("ruRU", "zanzil-the-outcast", {
	title = "Занзил Изгнанник",
	subtitle = "Изгнанный знахарь",
	found = "Руины Абораза, на Хрустальном взморье",
	hint = [=[Ищите знахаря-изгнанника в руинах к северо-востоку от Пиратской бухты.]=],
	allegiance = "Его собственные последователи",
	aliases = { "Занзил" },
	sections = {
		{
			title = "Обзор",
			text = [=[Занзил — тролль-знахарь, которого изгнало собственное племя. Вожди его боялись, и не без причины. Он умеет подчинять себе чужой разум. Из растений джунглей он варит зелье, которое притупляет волю тех, кто его пьет, и делает их тела сильными, и его последователи в руинах {link:ruins-of-aboraz-and-jubuwal}Абораз{/link}а и Жубуваля живут на этом зелье. Мертвецы, что там бродят, быть может, тоже обязаны ему своим состоянием.]=],
		},
		{
			title = "Значение",
			text = [=[Ремесло изгнанника разошлось дальше джунглей. Гоблины Пиратской бухты покупают образцы его зелья, и один из них научился превращать его в крепкий напиток для собственных затей. Далеко на севере лазутчики {link:si-7}SI:7{/link} узнали, что тролли знахаря умеют поднимать мертвых ядом и что эта тайна перешла в руки {link:defias-brotherhood}Братства Справедливости{/link}. В {link:tarren-mill}Мельнице Таррен{/link} безумие, которое несут его яды, изучал {link:serge-hinott}Серж Хинотт{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Племя изгнало его за власть над чужим разумом.
• Он предводительствует своими последователями в руинах {link:ruins-of-aboraz-and-jubuwal}Абораз{/link}а и Жубуваля.
• Он захватил мальчика из племени Черного Копья, {link:yenniku}Йеннику{/link}, и держал его телом и душой.
• Говорят, что его отвары поднимают мертвых.]=],
		},
	},
	chapters = {
		{
			title = "Зелье",
			hint = [=[Отнимите у последователей знахаря отвар, который их связывает.]=],
			text = [=[{link:crank-fizzlebub}Крэнк Физзлбаб{/link} прямо объяснил дело тем, кто готов был слушать. Зелье, способное подавить волю и закалить тело, дорого стоит для тех, кто хочет править другими. Он хорошо за него заплатил и еще немного прибавил за молчание.]=],
		},
		{
			title = "Украденная душа",
			hint = "Освободите юношу из племени Черного Копья из хватки знахаря.",
			text = [=[Власть изгнанника над пленником была так сильна, что разрушить ее могла только самая могучая магия. Знахари племени Черного Копья сотворили эту магию из самоцвета {link:ogres}огр{/link}а. Когда самоцвет души сомкнулся над духом пленника, Занзил лишился самого драгоценного из своих рабов.]=],
		},
	},
	mentions = {
		{ text = "Тайна знахаря Занзила" },
		{ text = "Судьба {link:yenniku}Йеннику{/link}" },
		{ text = "Спасение {link:yenniku}Йеннику{/link}" },
		{ text = "Обратно в Пиратскую бухту" },
		{ text = "Зелье знахаря Занзила и «Крепкое дурака»" },
		{ text = "Плата за вуду" },
		{ text = "Башня Клейвена" },
	},
	bonds = {
		{ id = "yenniku", name = "Йеннику", note = "его раб" },
		{ id = "crank-fizzlebub", name = "Крэнк Физзлбаб", note = "покупает его зелье" },
		{ id = "nimboya", name = "Нимбойя", note = "стремится отнять у него пленника" },
		{ id = "agent-kearnen", name = "Агент Кеарнен", note = "раскрыла след яда" },
		{ id = "serge-hinott", name = "Серж Хинотт", note = "лечит от его яда" },
	},
})

Translate("ruRU", "fleet-master-seahorn", {
	title = "Командующий флотом Морской Рог",
	subtitle = "Командующий флотом Пиратов Черноводья",
	found = "Пиратская бухта, близ покоев барона",
	hint = [=[Найдите старого морского волка, который командует флотом Черноводья в Пиратской бухте.]=],
	allegiance = "Пираты Черноводья · Пиратская бухта",
	aliases = { "Морской Рог" },
	sections = {
		{
			title = "Обзор",
			text = [=[Командующий флотом Морской Рог распоряжается кораблями пиратов, которые зовут Пиратскую бухту своим родным портом; это {red:blackwater-raiders}Пираты Черноводья{/red}. Его флот сейчас стоит в гавани, ожидая пополнения запасов, а его капитаны бороздят моря по его поручениям. Один из них, {link:shakes-o-breen}Трясун О'Брин{/link}, ушел на север, к побережью {link:arathi-highlands}Арати{/link}, за затонувшим эльфийским сокровищем. Морской Рог — старый морской волк, гордый своим флотом и презирающий соперников. Его соперники из Кровавого Паруса хотели бы видеть его мертвым.]=],
		},
	},
	chapters = {
		{
			title = "Заговор Кровавого Паруса",
			hint = [=[Узнайте, что пираты Кровавого Паруса замышляют против Пиратской бухты.]=],
			text = [=[Старший помощник Крэзз нашел в ялике к северу от порта карту, где красная метка стояла прямо на Пиратской бухте. Карты и приказы, взятые на посту Кровавого Паруса на Пустынном берегу, досказали остальное: командующий флотом {link:fleet-master-firallon}Фираллон{/link} задумал нападение, и его корабли бросили якорь у самого мыса. Морской Рог презрительно отозвался о нем как о человеке, который не сумел бы провести ялик через озеро. Свой флот он не послал. Вместо этого он отправил нескольких храбрых бойцов сразить главарей Кровавого Паруса.]=],
		},
	},
	mentions = {
		{ text = "Пираты Кровавого Паруса" },
		{ text = "Пираты Кровавого Паруса" },
		{ text = "Пираты Кровавого Паруса" },
		{ text = "Затонувшее сокровище" },
		{ text = "Затонувшее сокровище" },
	},
	bonds = {
		{ id = "shakes-o-breen", name = "Трясун О'Брин", note = "его капитан в Арати" },
		{ id = "fleet-master-firallon", name = "Командующий флотом Фираллон", note = "его соперник" },
		{ id = "baron-revilgaz", name = "Барон Ревилгаз", note = "владыка его родного порта" },
	},
})

Translate("ruRU", "fleet-master-firallon", {
	title = "Командующий флотом Фираллон",
	subtitle = "Командующий флотом пиратов Кровавого Паруса",
	found = "Под палубой «Кровавой Завесы», у Пустынного берега",
	hint = [=[Ищите пиратского капитана на борту «Кровавой Завесы», что стоит на якоре у Пустынного берега.]=],
	allegiance = "Пираты Кровавого Паруса",
